def _merge_legacy_codes_root(source: Path, target: Path) -> dict:
    """Import missing users/sessions from a legacy Codes root without overwrites."""
    result = {"imported_users": 0, "imported_sessions": 0, "skipped_sessions": 0, "errors": []}
